<script setup lang="ts">
import{ref,computed,onMounted,onUnmounted}from'vue';import{useRouter}from'vue-router';import{Search,MapPin,UserRound,X}from'lucide-vue-next';import{states,cities,loadLocations}from'../../composables/useLocations';import{elections}from'../../repositories/elections';import{normalize}from'../../utils/format';import {offices}from'../../types/election';import{candidateIndex as candidates,rememberCandidates,loadCandidateIndex,indexLoading,indexDone,indexFailed}from'../../composables/useCandidateIndex';
const router=useRouter(),query=ref(''),open=ref(false),root=ref<HTMLElement>(),index=ref(0);const results=computed(()=>{const q=normalize(query.value.trim());if(q.length<2)return[];return[...states.value.filter(s=>normalize(s.name).includes(q)||s.uf===q).map(s=>({label:s.name,description:'Estado',path:`/estado/${s.uf}`,type:'location'})),...cities.value.filter(c=>normalize(c.name).includes(q)).slice(0,7).map(c=>({label:c.name,description:states.value.find(s=>s.uf===c.uf)?.name||c.uf.toUpperCase(),path:`/estado/${c.uf}/${c.slug}`,type:'location'})),...candidates.value.filter(c=>normalize(c.name).includes(q)||c.number===q).slice(0,6).map(c=>({label:c.name,description:`${offices.find(o=>o.id===c.office)?.short} · ${c.party} · ${c.uf.toUpperCase()}`,path:`/candidato/${c.id}?uf=${c.uf}&cargo=${c.office}`,type:'candidate'}))].slice(0,12)});async function focus(){open.value=true;await loadLocations();if(!candidates.value.length)try{rememberCandidates((await elections.result()).candidates)}catch{}}function go(path:string){router.push(path);query.value='';open.value=false}function outside(e:MouseEvent){if(!root.value?.contains(e.target as Node))open.value=false}function key(e:KeyboardEvent){if(e.key==='Escape')open.value=false;if(e.key==='ArrowDown'){e.preventDefault();index.value=(index.value+1)%Math.max(results.value.length,1)}if(e.key==='ArrowUp'){e.preventDefault();index.value=(index.value-1+results.value.length)%Math.max(results.value.length,1)}if(e.key==='Enter'&&results.value[index.value])go(results.value[index.value].path)}onMounted(()=>document.addEventListener('click',outside));onUnmounted(()=>document.removeEventListener('click',outside));
</script>
<template><div ref="root" class="global-search"><Search :size="18"/><input v-model="query" aria-label="Buscar estado, município ou candidato" placeholder="Buscar estado, município ou candidato" role="combobox" :aria-expanded="open" aria-controls="global-results" :aria-activedescendant="results.length?'search-'+index:undefined" @focus="focus" @input="index=0;open=true" @keydown="key"><kbd v-if="!query">⌕</kbd><button v-else class="clear-search" aria-label="Limpar busca" @click="query='' "><X :size="15"/></button><div v-if="open&&query.length>=2" id="global-results" class="search-popover" role="listbox"><span class="popover-title">RESULTADOS DA BUSCA</span><button v-for="(r,i) in results" :id="'search-'+i" :key="r.path" role="option" :aria-selected="i===index" :class="{focused:i===index}" @click="go(r.path)"><UserRound v-if="r.type==='candidate'" :size="18"/><MapPin v-else :size="18"/><span><strong>{{r.label}}</strong><small>{{r.description}}</small></span></button><p v-if="!results.length">Nenhum resultado nas localidades e candidatos carregados.</p><button v-if="indexDone<27&&!indexLoading" class="index-search" @click="loadCandidateIndex">Buscar candidatos em todas as UFs</button><p v-if="indexLoading">Consultando candidatos: {{indexDone}} de 27 UFs…</p><p v-else-if="indexDone">Candidatos consultados em {{indexDone-indexFailed}} de 27 UFs.</p></div></div></template>
